css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .82); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 19%; width: 4%; height: 60%; border-radius: 2px; background: linear-gradient(color-mix(in srgb, #000 14%, var(--accent-2)), var(--accent-2)); }
.loader::before { content: ''; position: absolute; bottom: 54%; left: 8%; width: 26%; height: 32%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 72%, var(--accent)) 0 26%, transparent 28%), repeating-conic-gradient(from 0deg, var(--accent) 0 1.6deg, transparent 1.6deg 13deg); }
.loader span { position: absolute; bottom: 62%; left: 20%; width: 9%; height: 11%; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, #fff 55%, var(--accent)) 0 34%, transparent 36%), repeating-conic-gradient(from 0deg, var(--accent) 0 2deg, transparent 2deg 22deg); animation: drift-away calc(var(--loader-speed) * 2.8) ease-out infinite; }
.loader span:nth-child(1) { --dy: -.2; }
.loader span:nth-child(2) { --dy: .04; animation-delay: calc(var(--loader-speed) * .7); }
.loader span:nth-child(3) { --dy: -.34; animation-delay: calc(var(--loader-speed) * 1.4); }
.loader span:nth-child(4) { --dy: -.1; animation-delay: calc(var(--loader-speed) * 2.1); }
@keyframes drift-away { 0% { opacity: 0; transform: translate(0, 0) rotate(0deg); } 14% { opacity: 1; } 58% { transform: translate(calc(var(--loader-size) * .38), calc(var(--loader-size) * var(--dy) * .6)) rotate(190deg); } 100% { opacity: 0; transform: translate(calc(var(--loader-size) * .74), calc(var(--loader-size) * var(--dy))) rotate(350deg); } }
